# Sample work covers (clearly placeholders until real photos/videos are uploaded)
COVERS = {"wedding": "rings", "podcast": "mic", "coverage": "broadcast", "interview": "interview", "corporate": "corporate", "commercial": "megaphone"}
os.makedirs(os.path.join(ROOT, "public/art"), exist_ok=True)
for name, icon in COVERS.items():
    dots = []
    for y in range(0, 450, 18):
        for x in range(0, 800, 18):
            t = x / 800 + y / 450 * 0.4
            r = max(0, 3.4 * (1 - abs(t - 0.75) * 2.6))
            if r > 0.35: dots.append(f'<ellipse cx="{x}" cy="{y}" rx="{r:.2f}" ry="{r*1.3:.2f}"/>')
    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 450" width="800" height="450">
<defs><radialGradient id="g" cx="50%" cy="45%" r="65%"><stop offset="0" stop-color="#2a2217"/><stop offset="1" stop-color="#0c0b0a"/></radialGradient>
<linearGradient id="au" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#f6e2a0"/><stop offset=".5" stop-color="#d6b25e"/><stop offset="1" stop-color="#9c7428"/></linearGradient></defs>
<rect width="800" height="450" fill="url(#g)"/><g fill="#2b2620">{"".join(dots)}</g>
<g transform="translate(400 225) rotate(45)"><rect x="-118" y="-118" width="236" height="236" rx="10" fill="#0f0d0b" stroke="url(#au)" stroke-width="3"/></g>
<g transform="translate(322 147) scale(3.25)" fill="none" stroke="url(#au)" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">{SERVICE[icon]}</g>
</svg>'''
    open(os.path.join(ROOT, f"public/art/{name}.svg"), "w").write(svg)
print("ok")
